// Typical strength and health bonuses (%) by troop kind and level 1–9, for Tools → Citadel's
// "Suggest troops for my levels" when the player has no battle report to read theirs from —
// a baseline the page marks as one (the user, Nov 28 2026). Generated by
// research/monster-sim/bench/baseline-bonuses.mts from the latest real armies of 228
// players' shared reports (Nov 2026): a player's level in a kind is the highest tier of it
// they fielded; per kind and level, the median of each player's own median; flying and
// ground merged; a level of fewer than 5 players taken from its kind's nearest level 5+
// scaled as guardsmen grow (specialists 9 had 4 players at 6,734 %); made non-decreasing with
// the level; empty levels take the nearest. Regenerate (by hand) when armies have moved on.

/** kind → level (1–9) → [strength %, health %]. */
export const BASELINE_BONUSES = {"guardsmen":{"1":[44,79],"2":[44,79],"3":[44,79],"4":[44,295],"5":[630,447],"6":[1228,863],"7":[2075,1089],"8":[2773,1251],"9":[3767,1358]},"specialists":{"1":[81,174],"2":[81,174],"3":[81,174],"4":[484,408],"5":[1146,637],"6":[1602,898],"7":[2409,1062],"8":[3457,1318],"9":[4687,1430]},"monsters":{"1":[93,67],"2":[93,67],"3":[93,67],"4":[135,305],"5":[559,409],"6":[1091,711],"7":[1938,980],"8":[2734,1206],"9":[3791,1425]},"siege":{"1":[117,160],"2":[117,160],"3":[117,160],"4":[117,432],"5":[499,1137],"6":[989,1325],"7":[1583,1325],"8":[3497,1543],"9":[5398,1543]}};

/** The baseline for a troop: its kind at the player's level in that kind (else the troop's own tier). */
export function baselineBonus(kind, level) {
  const row = BASELINE_BONUSES[kind]?.[String(Math.min(9, Math.max(1, Math.round(level || 1))))];
  return row ? { strengthPct: row[0], healthPct: row[1] } : null;
}
